The following program demonstrates how to read from a file.

```
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    // open a file for reading
    FILE* fp = fopen("input.txt", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Unable to open input.txt for reading\n");
        exit(1);
    }

    // read in a line from the file
    char buf[1024];
    fgets(buf, sizeof(buf), fp);
    printf("buf: %s\n", buf);

    // close the file
    fclose(fp);
    return 0;
}
```

