## 2.2.3. 字符串替换

字符串替换是将一个字符串中的一个子串替换为另一个字符串的过程。

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // make sure 2 arguments were provided
    if (argc!= 3) {
        printf("Need 2 arguments\n");
        exit(1);
    }

    // get the arguments
    char *input = argv[1];
    char *old_str = argv[2];
    char *new_str = argv[3];

    // replace the old string with the new string
    char *result = strstr(input, old_str);
    if (result!= NULL) {
        int old_len = strlen(old_str);
        int new_len = strlen(new_str);
        int offset = result - input;
        int new_offset = offset + new_len;
        int new_size = strlen(input) + new_len - old_len;
        char *new_input = (char *) malloc(new_size + 1);
        strncpy(new_input, input, offset);
        strncpy(new_input + offset, new_str, new_len);
        strncpy(new_input + new_offset, input + offset + old_len, strlen(input) - offset - old_len);
        new_input[new_size] = '\0';
        printf("'%s' -> '%s'\n", input, new_input);
        free(new_input);
    } else {
        printf("'%s' does not contain '%s'\n", input, old_str);
    }

    return 0;
}
