```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // make sure 2 or more arguments were provided
    if (argc < 2) {
        printf("Need 2 or more arguments\n");
        exit(1);
    }

    // concatenate the arguments
    char *result = "";
    for (int i = 1; i < argc; i++) {
        result = strcat(result, argv[i]);
    }

    // print the result
    printf("'%s'\n", result);

    // free the result
    free(result);

    return 0;
}
```

