#define FILENAME "data.csv"

int main(int argc, char *argv[]) {
    // read from file
    FILE *fp = fopen(FILENAME, "r");
    char line[100];
    fgets(line, 100, fp);
    fclose(fp);

    // split line into 3 floats
    char *token;
    token = strtok(line, ",");
    float a = atof(token);
