int main(int argc, char *argv[]) {
    // open file
    FILE *fp = fopen(FILENAME, "r");
    if (fp == NULL) {
        printf("Error opening file!\n");
        return 1;
    }

    // read file
    char line[100];
    float sum = 0;
    int count = 0;
    while (fgets(line, 100, fp)!= NULL) {
        // split line into floats
        float a = 0;
        float b = 0;
        float c = 0;
        sscanf(line, "%f, %f, %f", &a, &b, &c);

        // calculate average
        float avg = (a + b + c) / 3;

        // print average
        printf("%.2f\n", avg);

        // add to sum
        sum += avg;
        count++;
    }

    // close file
    fclose(fp);

    // calculate average
    float avg = sum / count;

    // print average
    printf("Average: %.2f\n", avg);

    return 0;
}
