    int fd_write = fd[1];

    // 关闭写端
    close(fd_write);

    // 向管道写数据
    char buf[1024] = {0};
    sprintf(buf, "hello world");
    write(fd_read, buf, strlen(buf));

    // 关闭读端
    close(fd_read);

    return 0;
}
