int main(int argc, char *argv[]) {
    // get the source filename from the command line
    char *source = argv[1];

    // get the destination filename from the command line
    char *destination = argv[2];

    // open the source file
    int fd_source = open(source, O_RDONLY);
    if (fd_source == -1) {
        perror("open");
        exit(1);
