    // open the destination file
    int fd_destination = open(destination, O_WRONLY | O_CREAT, 0644);
    if (fd_destination == -1) {
        perror("open");
        exit(1);
    }

    // copy the file
    char buffer[100] = {0};
    while (read(fd_source, buffer, 100) > 0) {
        write(fd_destination, buffer, strlen(buffer));
    }

    // close the files
    close(fd_source);
    close(fd_destination);

    return 0;
}
