    free(tmp);

    // if we received no characters, set abort flag
    if (i == 0) {
        abort_flag = 1;
    }

    // if we received characters, store them in the array
    else {
        for (i = 0; i < ARRAY_SIZE; i++) {
            array[i] = tmp[i];
        }
    }

    // print the array
    for (i = 0; i < ARRAY_SIZE; i++) {
        printf("%c", array[i]);
    }

    // exit with a non-zero exit code if we aborted
    if (abort_flag) {
        exit(1);
    }

    return 0;
}
