    // open the file
    FILE *fp = fopen(argv[1], "r");
    if (fp == NULL) {
        printf("Error opening file\n");
        exit(1);
    }

    // read characters from the file into the temporary buffer
    int i = 0;
    while (1) {
        tmp[i] = fgetc(fp);
        if (tmp[i] == EOF) {
            break;
        }
        i++;
    }
    tmp[i] = '\0';

    // tidy up
