@app.route('/change_email', methods=['POST'])
@ensure_logged_in
def change_email():
    old_email = request.form['old_email']
    new_email = request.form['new_email']
    confirm_password = request.form['confirm_password']
    username = session['username']
    db = MySQLdb.connect(host="localhost", user="root", passwd="password", db="db")

# the secret page - must be logged in
@app.route('/secret', methods=['GET'])
@ensure_logged_in
def secret():
    return '''<html>
    Hello, {username}! Here's a secret message:
    <p>This is a secret message.</p>
    <p>You can change your email address <a href='/change_email'>here</a>.</p>
    </html>'''.format(username=session['username'])

